var w = GameState.get_unit("U_WEIRDBOY_A").meta.weapons.filter(func(x): return str(x.get("name", "")) == "Da Krunch")
if w.size() != 1:
	return "missing"
return "%d %s %s %s" % [w.size(), str(w[0].range), str(w[0].attacks), str(w[0].ap)]

var q = [tree.root]
var out := []
while not q.is_empty():
	var c = q.pop_front()
	if c is ItemList and c.is_visible_in_tree():
		for i in range(c.item_count):
			out.append(str(c.get_item_text(i)))
	elif (c is Label or c is Button or c is RichTextLabel) and c.is_visible_in_tree():
		out.append(str(c.get_parsed_text()) if c is RichTextLabel else str(c.text))
	for ch in c.get_children():
		q.append(ch)
return out.any(func(t): return t.contains("Da Krunch"))

var sc = tree.current_scene.get_node_or_null("ShootingController")
if sc and sc.resolution_dock and sc.resolution_dock.is_active():
	sc.resolution_dock.primary_button.emit_signal("pressed")
return true

